    assert.match(renamedList, /data-testid="project-summary">1\/2 completed/);
    assert.deepEqual([...renamedList.matchAll(/action="(\/projects\/\d+)"/g)].map(match => match[1]), paths);
    await stop();
    await start();
    assert.equal(await detailHtml(), renamedDetail);
